// 2025-1-11 16:47:02
// 非准周期点阵

#define PI 3.1415926535

void mainImage( out vec4 o, vec2 u )
{
        float N = floor(mod(iTime*4., 4.*30.))+3.;
        vec2 R = iResolution.xy, U;
        u = 200.*(u+u - R) / R.y;
        float s;
        for(float i=0.;i<N;i++)
        {
                U=  cos(PI/N*i+vec2(0,11));                
                s+=cos(dot(u,U));
        }
        o = vec4( .1*abs(s) );
}
